import os, io, re, json, uuid, secrets, zipfile
from datetime import datetime
from functools import wraps
from flask import Flask, request, jsonify, render_template_string, Response, redirect, session, send_file
from werkzeug.security import generate_password_hash, check_password_hash
from sqlalchemy import create_engine, text
import pandas as pd

app = Flask(__name__)
app.secret_key = os.environ.get("SECRET_KEY", "change-this-secret-in-vercel")
app.config.update(SESSION_COOKIE_HTTPONLY=True, SESSION_COOKIE_SAMESITE="Lax", SESSION_COOKIE_SECURE=os.environ.get("VERCEL") == "1")
DATABASE_URL = os.environ.get("DATABASE_URL") or os.environ.get("SUPABASE_DB_URL") or "sqlite:///local_portal.db"
if DATABASE_URL.startswith("postgres://"): DATABASE_URL = "postgresql+psycopg://" + DATABASE_URL[len("postgres://"):]
elif DATABASE_URL.startswith("postgresql://"): DATABASE_URL = "postgresql+psycopg://" + DATABASE_URL[len("postgresql://"):]
engine = create_engine(DATABASE_URL, pool_pre_ping=True, pool_recycle=300)
IS_PG = engine.dialect.name == "postgresql"

def now(): return datetime.utcnow().isoformat(timespec="seconds")
def clean_barcode(v):
    if v is None: return ""
    s=str(v).strip()
    if s.endswith('.0') and s[:-2].isdigit(): s=s[:-2]
    return re.sub(r'\\s+','',s)
def format_price(v):
    if v is None or (isinstance(v,float) and pd.isna(v)): return ''
    s=str(v).strip().replace(',','.')
    try: return f"{float(s):.2f}"
    except: return s

def init_db():
    pk = "BIGSERIAL PRIMARY KEY" if IS_PG else "INTEGER PRIMARY KEY AUTOINCREMENT"
    stmts=[
      "CREATE TABLE IF NOT EXISTS stores (id VARCHAR(36) PRIMARY KEY, name VARCHAR(160) NOT NULL, code VARCHAR(40) UNIQUE NOT NULL, bridge_key VARCHAR(120) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at VARCHAR(30) NOT NULL)",
      "CREATE TABLE IF NOT EXISTS portal_users (id VARCHAR(36) PRIMARY KEY, store_id VARCHAR(36) NOT NULL, username VARCHAR(80) NOT NULL, password_hash TEXT NOT NULL, full_name VARCHAR(160), role VARCHAR(30) NOT NULL DEFAULT 'user', active BOOLEAN NOT NULL DEFAULT TRUE, created_at VARCHAR(30) NOT NULL, UNIQUE(store_id,username))",
      "CREATE TABLE IF NOT EXISTS products (store_id VARCHAR(36) NOT NULL, barcode VARCHAR(120) NOT NULL, name TEXT NOT NULL, price_cx VARCHAR(40) DEFAULT '', price_emb VARCHAR(40) DEFAULT '', price_pc_kgm VARCHAR(40) DEFAULT '', price_bag VARCHAR(40) DEFAULT '', updated_at VARCHAR(30), PRIMARY KEY(store_id,barcode))",
      "CREATE TABLE IF NOT EXISTS ean_aliases (store_id VARCHAR(36) NOT NULL, ean_code VARCHAR(120) NOT NULL, article_code VARCHAR(120) NOT NULL, created_at VARCHAR(30), PRIMARY KEY(store_id,ean_code))",
      f"CREATE TABLE IF NOT EXISTS print_jobs (id {pk}, store_id VARCHAR(36) NOT NULL, article_code VARCHAR(120) NOT NULL, item_name TEXT NOT NULL, price VARCHAR(40) NOT NULL, unit VARCHAR(20) DEFAULT 'UN', currency VARCHAR(20) DEFAULT 'KZ', copies INTEGER DEFAULT 1, status VARCHAR(20) DEFAULT 'pending', created_at VARCHAR(30), claimed_at VARCHAR(30), printed_at VARCHAR(30), error_message TEXT)"
    ]
    with engine.begin() as c:
        for s in stmts: c.execute(text(s))
init_db()

def login_required(fn):
    @wraps(fn)
    def w(*a,**k):
        if not session.get('store_id'): return redirect('/login') if not request.path.startswith('/api/') else (jsonify(success=False,error='Login required'),401)
        return fn(*a,**k)
    return w

def developer_required(fn):
    @wraps(fn)
    def w(*a,**k):
        if not session.get('developer'): return redirect('/developer/login')
        return fn(*a,**k)
    return w

def sid(): return session.get('store_id')

