BRIDGE='''import os,time,requests\nBASE_URL=os.environ.get("PORTAL_URL","__URL__").rstrip("/")\nBRIDGE_KEY=os.environ.get("PRINT_BRIDGE_KEY","__KEY__")\nHEADERS={"X-Print-Bridge-Key":BRIDGE_KEY}\ndef print_label(job):\n print("PRINT",job["copies"],"x",job["item_name"],job["price"],job["currency"])\n # Replace this function with your Windows/Zebra/ESC-POS printer command.\nwhile True:\n try:\n  data=requests.get(BASE_URL+"/api/print-jobs/next",headers=HEADERS,timeout=20).json(); job=data.get("job")\n  if not job: time.sleep(3); continue\n  try:\n   print_label(job); payload={"success":True}\n  except Exception as e: payload={"success":False,"error":str(e)}\n  requests.post(BASE_URL+f"/api/print-jobs/{job['id']}/complete",headers=HEADERS,json=payload,timeout=20)\n except Exception as e: print("Bridge error:",e); time.sleep(5)\n'''
@app.get('/developer/store/<store_id>/bridge.zip')
@developer_required
def bridge_zip(store_id):
    with engine.connect() as c: s=c.execute(text("SELECT * FROM stores WHERE id=:i"),{'i':store_id}).mappings().first()
    if not s: return 'Store not found',404
    base=os.environ.get('PORTAL_PUBLIC_URL',request.url_root.rstrip('/'))
    code=BRIDGE.replace('__URL__',base).replace('__KEY__',s['bridge_key'])
    b=io.BytesIO()
    with zipfile.ZipFile(b,'w',zipfile.ZIP_DEFLATED) as z:
        z.writestr('local_bridge.py',code); z.writestr('requirements.txt','requests==2.32.3\n'); z.writestr('run_bridge.bat','@echo off\npy -m pip install -r requirements.txt\npy local_bridge.py\npause\n'); z.writestr('README.txt','1. Install Python 3.\n2. Double-click run_bridge.bat.\n3. Keep window open near printer.\nEdit print_label() for your printer driver.\n')
    b.seek(0); return send_file(b,as_attachment=True,download_name=f"{s['code']}_local_bridge.zip",mimetype='application/zip')

