@app.get('/api/sync-all')
@login_required
def sync_all():
    canonical=request.args.get('canonical')=='1'
    with engine.connect() as c:
        pc=c.execute(text("SELECT COUNT(*) FROM products WHERE store_id=:s"),{'s':sid()}).scalar()
        if canonical: rows=c.execute(text("SELECT barcode,name,price_cx,price_emb,price_pc_kgm,price_bag,updated_at FROM products WHERE store_id=:s"),{'s':sid()}).mappings().all(); items=[dict(x) for x in rows]
        else:
            rows=c.execute(text("SELECT e.ean_code search_key,p.barcode,p.name,p.price_cx,p.price_emb,p.price_pc_kgm,p.price_bag,p.updated_at FROM products p JOIN ean_aliases e ON e.store_id=p.store_id AND e.article_code=p.barcode WHERE p.store_id=:s"),{'s':sid()}).mappings().all(); items=[]
            for x in rows: d=dict(x); d['article_code']=d['barcode']; d['barcode']=d.pop('search_key'); items.append(d)
    return jsonify(success=True,count=len(items),product_count=pc,items=items)

