@app.get('/api/print-jobs/next')
def next_job():
    s=bridge_store()
    if not s:return jsonify(success=False,error='Unauthorized'),401
    with engine.begin() as c:
        row=c.execute(text("SELECT * FROM print_jobs WHERE store_id=:s AND status='pending' ORDER BY id LIMIT 1 FOR UPDATE SKIP LOCKED" if IS_PG else "SELECT * FROM print_jobs WHERE store_id=:s AND status='pending' ORDER BY id LIMIT 1"),{'s':s}).mappings().first()
        if row:c.execute(text("UPDATE print_jobs SET status='claimed',claimed_at=:t WHERE id=:i"),{'t':now(),'i':row['id']})
    return jsonify(success=True,job=dict(row) if row else None)
@app.post('/api/print-jobs/<int:job_id>/complete')
def complete_job(job_id):
    s=bridge_store()
    if not s:return jsonify(success=False,error='Unauthorized'),401
    d=request.get_json() or {}; ok=bool(d.get('success'))
    with engine.begin() as c:c.execute(text("UPDATE print_jobs SET status=:st,printed_at=:pt,error_message=:e WHERE id=:i AND store_id=:s"),{'st':'printed' if ok else 'pending','pt':now() if ok else None,'e':None if ok else str(d.get('error','Print failed'))[:500],'i':job_id,'s':s})
    return jsonify(success=True)

@app.post('/api/preview-excel')
@login_required
def preview_excel():
    f=request.files.get('file')
    if not f:return jsonify(success=False,error='No file uploaded'),400
    try:
        df=pd.read_excel(f) if not f.filename.lower().endswith('.csv') else pd.read_csv(f)
        return jsonify(success=True,columns=[str(x) for x in df.columns],rows=df.fillna('').head(12).astype(str).to_dict('records'))
    except Exception as e:return jsonify(success=False,error=str(e)),400

@app.post('/api/import-mapped')
@login_required
def import_mapped():
    f=request.files.get('file'); mapping=json.loads(request.form.get('mapping','{}'))
    if not f:return jsonify(success=False,error='No file uploaded'),400
    try: df=pd.read_excel(f) if not f.filename.lower().endswith('.csv') else pd.read_csv(f)
    except Exception as e:return jsonify(success=False,error=str(e)),400
    ac=mapping.get('article_code') or mapping.get('barcode'); nc=mapping.get('name'); ec=mapping.get('ean')
    if not ac or ac not in df.columns:return jsonify(success=False,error='Map article/barcode column'),400
    new=upd=skip=aliases=0; t=now()
    with engine.begin() as c:
      for _,r in df.iterrows():
        b=clean_barcode(r.get(ac));
        if not b: skip+=1; continue
        name=str(r.get(nc) if nc and nc in df.columns else b).strip() or b
        prices={k:format_price(r.get(col,'')) if col in df.columns else '' for k,col in mapping.items() if k in ['price_cx','price_emb','price_pc_kgm','price_bag']}
        prices={**{'price_cx':'','price_emb':'','price_pc_kgm':'','price_bag':''},**prices}
        exists=c.execute(text("SELECT 1 FROM products WHERE store_id=:s AND barcode=:b"),{'s':sid(),'b':b}).scalar()
        if exists:
          c.execute(text("UPDATE products SET name=:n,price_cx=CASE WHEN :cx<>'' THEN :cx ELSE price_cx END,price_emb=CASE WHEN :em<>'' THEN :em ELSE price_emb END,price_pc_kgm=CASE WHEN :pc<>'' THEN :pc ELSE price_pc_kgm END,price_bag=CASE WHEN :bg<>'' THEN :bg ELSE price_bag END,updated_at=:t WHERE store_id=:s AND barcode=:b"),{'n':name,'cx':prices['price_cx'],'em':prices['price_emb'],'pc':prices['price_pc_kgm'],'bg':prices['price_bag'],'t':t,'s':sid(),'b':b}); upd+=1
        else:
          c.execute(text("INSERT INTO products(store_id,barcode,name,price_cx,price_emb,price_pc_kgm,price_bag,updated_at) VALUES(:s,:b,:n,:cx,:em,:pc,:bg,:t)"),{'s':sid(),'b':b,'n':name,'cx':prices['price_cx'],'em':prices['price_emb'],'pc':prices['price_pc_kgm'],'bg':prices['price_bag'],'t':t}); new+=1
        eans=[b]
        if ec and ec in df.columns:eans += [clean_barcode(x) for x in re.split(r'[,;|/\\s]+',str(r.get(ec,''))) if clean_barcode(x)]
        for e in dict.fromkeys(eans):
          if IS_PG:c.execute(text("INSERT INTO ean_aliases(store_id,ean_code,article_code,created_at) VALUES(:s,:e,:b,:t) ON CONFLICT(store_id,ean_code) DO UPDATE SET article_code=EXCLUDED.article_code"),{'s':sid(),'e':e,'b':b,'t':t})
          else:c.execute(text("INSERT OR REPLACE INTO ean_aliases(store_id,ean_code,article_code,created_at) VALUES(:s,:e,:b,:t)"),{'s':sid(),'e':e,'b':b,'t':t})
          aliases+=1
      total=c.execute(text("SELECT COUNT(*) FROM products WHERE store_id=:s"),{'s':sid()}).scalar()
    return jsonify(success=True,new_added=new,existing_updated=upd,ean_linked=aliases,skipped=skip,total_products=total)

if __name__=='__main__': app.run(host='0.0.0.0',port=int(os.environ.get('PORT',5000)),debug=True)
